DROP TABLE IF EXISTS `servizi_express_richieste`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `servizi_express_richieste` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `cliente_id` int unsigned NOT NULL,
  `prodotto_id` int unsigned DEFAULT NULL,
  `titolo` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tipo_richiesta` enum('Purchase','Reservation','Deposit','Installment','Support') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Purchase',
  `stato` enum('Pending','InReview','Confirmed','Completed','Cancelled','Declined') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Pending',
  `importo_acconto` decimal(10,2) DEFAULT NULL,
  `numero_rate` int unsigned DEFAULT NULL,
  `metodo_pagamento` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `data_desiderata` date DEFAULT NULL,
  `note_cliente` text COLLATE utf8mb4_unicode_ci,
  `nota_interna` text COLLATE utf8mb4_unicode_ci,
  `gestita_da` int DEFAULT NULL,
  `gestita_il` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_servizi_express_richieste_cliente` (`cliente_id`),
  KEY `idx_servizi_express_richieste_prodotto` (`prodotto_id`),
  KEY `idx_servizi_express_richieste_stato` (`stato`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
